import os
import base64
from typing import Union

import requests


def _encode_image_input(image: Union[str, bytes]) -> str:
    if isinstance(image, bytes):
        return base64.b64encode(image).decode("utf-8")

    if isinstance(image, str):
        if image.startswith("http://") or image.startswith("https://"):
            resp = requests.get(image, timeout=30)
            resp.raise_for_status()
            return base64.b64encode(resp.content).decode("utf-8")

        with open(image, "rb") as f:
            return base64.b64encode(f.read()).decode("utf-8")

    raise TypeError("image must be a local file path, URL, or raw bytes")


def generate_visual_description(image: Union[str, bytes]) -> str:
    api_key = os.getenv("DASHSCOPE_API_KEY")
    if not api_key:
        raise EnvironmentError("DASHSCOPE_API_KEY is required")

    image_b64 = _encode_image_input(image)

    url = "https://dashscope-intl.aliyuncs.com/compatible-mode/v1/chat/completions"
    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
    }
    payload = {
        "model": "qwen-vl-max",
        "messages": [
            {
                "role": "user",
                "content": [
                    {
                        "type": "text",
                        "text": "Write a short visual description of this image in one or two sentences.",
                    },
                    {
                        "type": "image_url",
                        "image_url": {"url": f"data:image/jpeg;base64,{image_b64}"},
                    },
                ],
            }
        ],
        "max_tokens": 120,
        "temperature": 0.2,
    }

    response = requests.post(url, headers=headers, json=payload, timeout=60)
    response.raise_for_status()
    data = response.json()

    try:
        return data["choices"][0]["message"]["content"].strip()
    except (KeyError, IndexError, AttributeError):
        raise RuntimeError(f"Unexpected response format: {data}")
